// Evita repetir la MISMA alerta cada minuto (espera 10 min).
// Nota: al probar con "Execute workflow" a mano, n8n no guarda esta memoria,
// así que en pruebas manuales siempre alerta. Con el flujo activo sí la guarda.
function primeraVez(clave, minutos = 10) {
  const sd = $getWorkflowStaticData('global');
  const ahora = Date.now();
  sd.vistos = sd.vistos || {};
  for (const k of Object.keys(sd.vistos)) {
    if (ahora - sd.vistos[k] > 24 * 3600 * 1000) delete sd.vistos[k];
  }
  if (sd.vistos[clave] && ahora - sd.vistos[clave] < minutos * 60 * 1000) return false;
  sd.vistos[clave] = ahora;
  return true;
}

// H5: desvío del baseline de seguridad (pg_settings_baseline de M2)
const filas = $input.all().map(i => i.json).filter(r => r.name);
if (filas.length === 0) return [];
const clave = 'H5:' + filas.map(r => r.name + '=' + r.actual).sort().join('|');
if (!primeraVez(clave)) return [];
return [{ json: {
  codigo: 'H5',
  severidad: 'CRÍTICA',
  tipo: 'Desvío del baseline de seguridad',
  tabla: 'pg_settings_baseline',
  detalle: 'Parámetros fuera de baseline: ' + filas.map(r => `${r.name} = ${r.actual} (esperado: ${r.valor_esperado})`).join('; '),
  query: 'ALTER SYSTEM SET ...',
  usuario: 'N/A (revisar log de PostgreSQL)',
  accion: 'Restaurar el valor seguro: ALTER SYSTEM RESET <parámetro>; SELECT pg_reload_conf();'
}}];
